package com.minhas.teller.utils

import com.minhas.teller.data.entities.HsnEntry

/**
 * Brand / common-name → HSN aliases for everyday Indian retail items.
 *
 * The full 21k-code CBIC directory (hsn_codes.txt) only carries official tariff descriptions,
 * so a brand like "Splendor" or "Cadbury Dairy Milk" never matches "Motorcycles…" or
 * "Chocolate…". These entries add consumer-friendly keywords so Smart Tax can classify a
 * product by its brand / common name and auto-fill the right HSN + GST rate.
 *
 * Rates mirror the bundled directory (HsnPresetData) for the same code, so the two never
 * disagree. To ship new aliases, add them here and bump HsnPresetData.DATA_VERSION — the app
 * re-syncs the directory on the next lookup.
 */
object HsnCommonItems {

    fun entries(): List<HsnEntry> = baseEntries() + HsnStoreCatalogs.allStoreEntries()

